<?php
$subjects=$db->query("SELECT id,name FROM subjects WHERE status='active' ORDER BY name")->fetchAll();$materials=$db->query('SELECT id,subject_id,title FROM materials ORDER BY title')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM questions WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$showForm=isset($_GET['create'])||$edit;
$subjectFilter=(int)($_GET['subject_id']??0);$statusFilter=(string)($_GET['status']??'');$conditions=[];$params=[];if($subjectFilter){$conditions[]='q.subject_id=?';$params[]=$subjectFilter;}if(in_array($statusFilter,['draft','reviewed','approved','rejected'],true)){$conditions[]='q.status=?';$params[]=$statusFilter;}$sql="SELECT q.*,s.name subject_name,m.title material_title FROM questions q JOIN subjects s ON s.id=q.subject_id LEFT JOIN materials m ON m.id=q.material_id".($conditions?' WHERE '.implode(' AND ',$conditions):'').' ORDER BY q.updated_at DESC';$stmt=$db->prepare($sql);$stmt->execute($params);$questions=$stmt->fetchAll();
?>
<div class="section-title"><div><h2>Bank soal pilihan ganda</h2><p>Semua soal memakai tepat empat pilihan, A sampai D.</p></div><a class="btn btn-primary" href="<?= url('questions',['create'=>1]) ?>"><?= icon('plus',17) ?> Tambah soal</a></div>
<?php if($showForm): ?><section class="card"><div class="card-header"><div><h2><?= $edit?'Edit':'Tambah' ?> soal</h2><p>Pastikan hanya satu jawaban yang benar dan seluruh opsi berbeda.</p></div></div><div class="card-body"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_question"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="form-grid"><div class="form-group"><label>Mata pelajaran *</label><select class="form-control" name="subject_id" required data-subject-filter><option value="">Pilih mata pelajaran</option><?php foreach($subjects as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['subject_id']??'', $item['id']) ?>><?= e($item['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Materi sumber</label><select class="form-control" name="material_id" data-material-select><option value="">Tanpa materi</option><?php foreach($materials as $item): ?><option data-subject="<?= $item['subject_id'] ?>" value="<?= $item['id'] ?>" <?= selected($edit['material_id']??'', $item['id']) ?>><?= e($item['title']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label>Pertanyaan *</label><textarea class="form-control" name="question_text" required><?= e($edit['question_text']??'') ?></textarea></div><?php foreach(['a'=>'A','b'=>'B','c'=>'C','d'=>'D'] as $key=>$letter): ?><div class="form-group"><label>Pilihan <?= $letter ?> *</label><input class="form-control" name="option_<?= $key ?>" required value="<?= e($edit['option_'.$key]??'') ?>"></div><?php endforeach; ?><div class="form-group"><label>Kunci jawaban *</label><select class="form-control" name="correct_option" required><?php foreach(['A','B','C','D'] as $letter): ?><option value="<?= $letter ?>" <?= selected($edit['correct_option']??'A',$letter) ?>><?= $letter ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Tingkat kesulitan</label><select class="form-control" name="difficulty"><?php foreach(['mudah'=>'Mudah','sedang'=>'Sedang','sulit'=>'Sulit'] as $key=>$label): ?><option value="<?= $key ?>" <?= selected($edit['difficulty']??'sedang',$key) ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Level kognitif</label><select class="form-control" name="cognitive_level"><?php foreach(['C1','C2','C3','C4','C5','C6'] as $level): ?><option <?= selected($edit['cognitive_level']??'C2',$level) ?>><?= $level ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Status validasi</label><select class="form-control" name="status"><?php foreach(['draft'=>'Draf','reviewed'=>'Ditinjau','approved'=>'Disetujui','rejected'=>'Ditolak'] as $key=>$label): ?><option value="<?= $key ?>" <?= selected($edit['status']??'draft',$key) ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="form-group full"><label>Pembahasan</label><textarea class="form-control" name="explanation"><?= e($edit['explanation']??'') ?></textarea></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?= url('questions') ?>">Batal</a><button class="btn btn-primary">Simpan soal</button></div></form></div></section><?php endif; ?>
<form id="print-form" method="post" action="print.php" target="_blank"></form><section class="card mt-3"><div class="card-header"><div><h2>Semua soal</h2><p><?= count($questions) ?> soal ditemukan</p></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="questions"><select class="form-control" name="subject_id"><option value="">Semua mapel</option><?php foreach($subjects as $item): ?><option value="<?= $item['id'] ?>" <?= selected($subjectFilter,$item['id']) ?>><?= e($item['name']) ?></option><?php endforeach; ?></select><select class="form-control" name="status"><option value="">Semua status</option><?php foreach(['draft'=>'Draf','reviewed'=>'Ditinjau','approved'=>'Disetujui','rejected'=>'Ditolak'] as $key=>$label): ?><option value="<?= $key ?>" <?= selected($statusFilter,$key) ?>><?= $label ?></option><?php endforeach; ?></select><button class="btn btn-secondary btn-sm">Filter</button></form></div><div class="card-body no-print" style="padding-bottom:0"><div class="filter-bar"><label class="text-sm"><input type="checkbox" data-select-all=".question-select"> Pilih semua</label><button class="btn btn-secondary btn-sm" type="submit" form="print-form"><?= icon('print',15) ?> Cetak soal terpilih</button><div class="search-box"><?= icon('search',17) ?><input class="form-control" type="search" placeholder="Cari soal..." data-filter-table="#question-table"></div></div></div><div class="table-wrap"><table class="data-table" id="question-table"><thead><tr><th class="no-print"></th><th>Soal</th><th>Sumber</th><th>Kualitas</th><th>Status</th><th class="no-print"></th></tr></thead><tbody><?php foreach($questions as $item): ?><tr><td class="no-print"><input class="question-select" type="checkbox" name="ids[]" form="print-form" value="<?= $item['id'] ?>"></td><td><strong><?= e($item['question_text']) ?></strong><div class="muted text-sm">Kunci: <?= e($item['correct_option']) ?> • <?= e(ucfirst($item['difficulty'])) ?> • <?= e($item['cognitive_level']) ?></div></td><td><?= e($item['subject_name']) ?><div class="muted text-sm"><?= e($item['material_title']?:'Manual') ?></div></td><td><?= e($item['source_type']==='generator'?'Generator':'Manual') ?></td><td><?= status_badge($item['status']) ?></td><td class="no-print"><div class="actions"><a class="btn btn-secondary btn-sm" href="<?= url('questions',['edit'=>$item['id']]) ?>"><?= icon('edit',14) ?></a><form method="post" data-confirm="Hapus soal ini?"><?= csrf_field() ?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-danger btn-sm"><?= icon('trash',14) ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$questions): ?><tr><td colspan="6"><div class="empty-state"><h3>Belum ada soal</h3><p>Buat soal manual atau gunakan generator berdasarkan materi.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
